CREATE TABLE `base_product` (
  `name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `brand` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` longtext COLLATE utf8mb4_unicode_ci,
  `createdAt` datetime(6) NOT NULL,
  `_id` int NOT NULL AUTO_INCREMENT,
  `city` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_approved` tinyint(1) NOT NULL,
  `user_id` int DEFAULT NULL,
  `business_phone` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `personal_phone` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address` longtext COLLATE utf8mb4_unicode_ci,
  `area_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `closing_time` time(6) DEFAULT NULL,
  `opening_time` time(6) DEFAULT NULL,
  `claimed_at` datetime(6) DEFAULT NULL,
  `claimed_by_id` int DEFAULT NULL,
  `is_claimed` tinyint(1) NOT NULL,
  `attributes` json NOT NULL DEFAULT (_utf8mb4'{}'),
  `available_since` datetime(6) DEFAULT NULL,
  `is_available_today` tinyint(1) NOT NULL,
  `website_url` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `instagram_url` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `max_price` decimal(10,2) DEFAULT NULL,
  `min_price` decimal(10,2) DEFAULT NULL,
  `video_duration` double DEFAULT NULL,
  `video_thumb` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `video_uploaded_at` datetime(6) DEFAULT NULL,
  `video_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`_id`),
  UNIQUE KEY `base_product_name_1f9bf170_uniq` (`name`),
  UNIQUE KEY `base_product_user_id_95204f5a_uniq` (`user_id`),
  KEY `base_product_claimed_by_id_66c26a1c_fk_auth_user_id` (`claimed_by_id`),
  KEY `base_product_video_thumb_ef3d0a43` (`video_thumb`),
  KEY `base_product_video_url_270334a5` (`video_url`),
  CONSTRAINT `base_product_claimed_by_id_66c26a1c_fk_auth_user_id` FOREIGN KEY (`claimed_by_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `base_product_user_id_95204f5a_fk_auth_user_id` FOREIGN KEY (`user_id`) REFERENCES `auth_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=794 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
