--
-- Table structure for table `base_review`
--

DROP TABLE IF EXISTS `base_review`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `base_review` (
  `name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rating` int DEFAULT NULL,
  `comment` longtext COLLATE utf8mb4_unicode_ci,
  `createdAt` datetime(6) NOT NULL,
  `_id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `service_id` int DEFAULT NULL,
  PRIMARY KEY (`_id`),
  KEY `base_review_user_id_9a731b84_fk_auth_user_id` (`user_id`),
  KEY `base_review_service_id_4531d3da_fk_base_service__id` (`service_id`),
  CONSTRAINT `base_review_service_id_4531d3da_fk_base_service__id` FOREIGN KEY (`service_id`) REFERENCES `base_service` (`_id`),
  CONSTRAINT `base_review_user_id_9a731b84_fk_auth_user_id` FOREIGN KEY (`user_id`) REFERENCES `auth_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3803 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

